import { createClient } from '@supabase/supabase-js';
import fs from 'fs';
import path from 'path';

const DEFAULT_STORE_ID = 'trending-juice';

/**
 * The store's catalogue, read from the committed menu snapshot.
 *
 * This was a hand-written copy of the *previous* tenant's Indo-Chinese menu —
 * 11 categories and 80 items. Running this script would have overwritten a
 * juice bar's Supabase catalogue with fried rice and biryani.
 *
 * src/data/menu-snapshot.json is regenerated by scripts/build-menu-snapshot.js
 * on every build, so reading it here means one catalogue rather than three.
 */
function loadSnapshot() {
  const snapshotPath = path.join(process.cwd(), 'src', 'data', 'menu-snapshot.json');
  try {
    return JSON.parse(fs.readFileSync(snapshotPath, 'utf8'));
  } catch (error) {
    throw new Error(
      `[update-menu] Could not read ${snapshotPath}. Run "npm run build" first. (${error.message})`
    );
  }
}

const SNAPSHOT = loadSnapshot();

const NEW_CATEGORIES = SNAPSHOT.categories.map((category, index) => ({
  name: category.name,
  icon: category.icon || '',
  sort_order: index + 1
}));

const NEW_MENU_ITEMS = SNAPSHOT.categories.flatMap(category =>
  category.items.map(item => [category.name, item.name, item.price, item.isVeg !== false])
);

function loadEnv() {
  const vars = { ...process.env };
  const filePath = path.resolve(process.cwd(), '.env');
  if (fs.existsSync(filePath)) {
    for (const line of fs.readFileSync(filePath, 'utf8').split(/\r?\n/)) {
      const match = line.match(/^\s*([^#=]+)\s*=\s*(.*)\s*$/);
      if (!match) continue;
      let value = match[2].trim();
      if ((value.startsWith('"') && value.endsWith('"')) || (value.startsWith("'") && value.endsWith("'"))) {
        value = value.slice(1, -1);
      }
      vars[match[1].trim()] = value;
    }
  }
  return vars;
}

async function main() {
  const env = loadEnv();
  const supabaseUrl = env.NEXT_PUBLIC_SUPABASE_URL;
  const serviceRoleKey = env.SUPABASE_SERVICE_ROLE_KEY;
  const storeId = env.STORE_ID || DEFAULT_STORE_ID;

  if (!supabaseUrl || !serviceRoleKey) {
    console.error('Error: NEXT_PUBLIC_SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY must be defined in .env');
    process.exit(1);
  }

  console.log(`Connecting to Supabase at ${supabaseUrl}...`);
  const client = createClient(supabaseUrl, serviceRoleKey, {
    auth: { autoRefreshToken: false, persistSession: false }
  });

  // 1. Delete existing items
  console.log(`Deleting existing menu items for store: ${storeId}...`);
  const { error: delItemsErr } = await client
    .from('menu_items')
    .delete()
    .eq('store_id', storeId);
  if (delItemsErr) throw delItemsErr;

  // 2. Delete existing categories
  console.log(`Deleting existing menu categories for store: ${storeId}...`);
  const { error: delCatsErr } = await client
    .from('menu_categories')
    .delete()
    .eq('store_id', storeId);
  if (delCatsErr) throw delCatsErr;

  // 3. Insert categories
  console.log('Inserting new categories...');
  const catRows = NEW_CATEGORIES.map((cat, idx) => ({
    id: idx + 1,
    store_id: storeId,
    name: cat.name,
    icon: cat.icon,
    sort_order: cat.sort_order,
    is_active: true,
    updated_at: new Date().toISOString()
  }));

  const { data: insertedCats, error: insCatsErr } = await client
    .from('menu_categories')
    .insert(catRows)
    .select();
  if (insCatsErr) throw insCatsErr;
  console.log(`Successfully inserted ${insertedCats.length} categories.`);

  // Create a mapping of category name to ID
  const catMap = new Map(insertedCats.map(cat => [cat.name, cat.id]));

  // 4. Insert menu items
  console.log('Inserting new menu items...');
  const itemRows = NEW_MENU_ITEMS.map(([categoryName, name, price, isVeg], index) => {
    const categoryId = catMap.get(categoryName);
    if (!categoryId) {
      throw new Error(`Category matching "${categoryName}" was not found!`);
    }
    return {
      id: index + 1,
      store_id: storeId,
      category_id: categoryId,
      name,
      price: Number(price),
      is_available: true,
      is_veg: isVeg,
      sort_order: index + 1,
      image_url: '',
      updated_at: new Date().toISOString()
    };
  });

  const { data: insertedItems, error: insItemsErr } = await client
    .from('menu_items')
    .insert(itemRows)
    .select();
  if (insItemsErr) throw insItemsErr;

  console.log(`Successfully inserted ${insertedItems.length} menu items.`);
  console.log('Menu update complete in Supabase!');
}

main().catch(err => {
  console.error('Failed to update menu in Supabase:', err);
  process.exit(1);
});
